1	/**
2	 * Code Block Plugin
3	 *
4	 * Implements syntax highlighting preview for Markdown code blocks
5	 * Shows rendered result when cursor is outside code block, shows source when inside
6	 * Supports precise click position mapping
7	 *
8	 * Modes:
9	 * - auto: shows rendered widget normally, switches to source on cursor enter
10	 * - toggle: shows rendered widget by default, requires explicit button click for source
11	 * - inline: replaces only fence lines, keeps code content in contentDOM for native editing
12	 */
13	
14	import { syntaxTree } from '@codemirror/language';
15	import { EditorState, Extension, Range, StateField } from '@codemirror/state';
16	import {
17	  Decoration,
18	  DecorationSet,
19	  EditorView,
20	  ViewPlugin,
21	  ViewUpdate,
22	  WidgetType,
23	} from '@codemirror/view';
24	import { shouldShowSource } from '../core/shouldShowSource';
25	import { mouseSelectingField } from '../core/mouseSelecting';
26	import {
27	  createCodeBlockSourceToggleWidget,
28	  createCodeBlockWidget,
29	} from '../widgets/codeBlockWidget';
30	import { highlightCodeHast } from '../utils/codeHighlight';
31	import {
32	  CodeBlockSourceModeToggle,
33	  setCodeBlockSourceMode,
34	} from './codeBlockEffects';
35	
36	/**
37	 * Code block plugin configuration
38	 */
39	export interface CodeBlockOptions {
40	  /** Whether to show line numbers, default false */
41	  lineNumbers?: boolean;
42	  /** Whether to show copy button, default true */
43	  copyButton?: boolean;
44	  /** Default language, default 'text' */
45	  defaultLanguage?: string;
46	  /** Interaction mode: auto follows cursor, toggle uses explicit button, inline keeps code editable */
47	  interaction?: 'auto' | 'toggle' | 'inline';
48	}
49	
50	export interface CodeBlockEditorOptions
51	  extends Omit<CodeBlockOptions, 'interaction'> {}
52	
53	const defaultOptions: Required<CodeBlockOptions> = {
54	  lineNumbers: false,
55	  copyButton: true,
56	  defaultLanguage: 'text',
57	  interaction: 'auto',
58	};
59	
60	/**
61	 * Languages to skip (handled by other plugins)
62	 */
63	const SKIP_LANGUAGES = new Set(['math']);
64	
65	interface CodeBlockSourceRange {
66	  from: number;
67	  to: number;
68	}
69	
70	function rangesOverlap(a: CodeBlockSourceRange, b: CodeBlockSourceRange): boolean {
71	  return a.from <= b.to && a.to >= b.from;
72	}
73	
74	function removeRange(
75	  ranges: CodeBlockSourceRange[],
76	  target: CodeBlockSourceRange
77	): CodeBlockSourceRange[] {
78	  return ranges.filter((range) => !rangesOverlap(range, target));
79	}
80	
81	function addRange(
82	  ranges: CodeBlockSourceRange[],
83	  next: CodeBlockSourceRange
84	): CodeBlockSourceRange[] {
85	  if (ranges.some((range) => rangesOverlap(range, next))) {
86	    return ranges;
87	  }
88	  return [...ranges, next];
89	}
90	
91	function isCodeBlockInSourceMode(
92	  ranges: CodeBlockSourceRange[],
93	  from: number,
94	  to: number
95	): boolean {
96	  return ranges.some((range) => range.from <= to && range.to >= from);
97	}
98	
99	const codeBlockSourceModeField = StateField.define<CodeBlockSourceRange[]>({
100	  create: () => [],
101	  update(ranges, tr) {
102	    let next = ranges.map((range) => ({
103	      from: tr.changes.mapPos(range.from, 1),
104	      to: tr.changes.mapPos(range.to, -1),
105	    }));
106	
107	    for (const effect of tr.effects) {
108	      if (!effect.is(setCodeBlockSourceMode)) continue;
109	      const { from, to, showSource } = effect.value as CodeBlockSourceModeToggle;
110	      const mapped = {
111	        from: tr.changes.mapPos(from, 1),
112	        to: tr.changes.mapPos(to, -1),
113	      };
114	      next = showSource ? addRange(next, mapped) : removeRange(next, mapped);
115	    }
116	
117	    return next;
118	  },
119	});
120	
121	// ─── Inline mode widgets ───────────────────────────────────────────────
122	
123	/**
124	 * Header widget replacing the opening fence line (```lang)
125	 * Shows language badge, copy button, and MD (source-toggle) button
126	 */
127	class CodeBlockHeaderWidget extends WidgetType {
128	  constructor(
129	    readonly language: string,
130	    readonly code: string,
131	    readonly from: number,
132	    readonly to: number,
133	    readonly showCopyButton: boolean
134	  ) {
135	    super();
136	  }
137	
138	  eq(other: CodeBlockHeaderWidget): boolean {
139	    return (
140	      other.language === this.language &&
141	      other.code === this.code &&
142	      other.from === this.from &&
143	      other.to === this.to &&
144	      other.showCopyButton === this.showCopyButton
145	    );
146	  }
147	
148	  toDOM(view?: EditorView): HTMLElement {
149	    const header = document.createElement('div');
150	    header.className = 'cm-codeblock-header';
151	
152	    // Language badge
153	    if (this.language && this.language !== 'text') {
154	      const badge = document.createElement('span');
155	      badge.className = 'cm-codeblock-lang';
156	      badge.textContent = this.language;
157	      header.appendChild(badge);
158	    }
159	
160	    // Spacer
161	    const spacer = document.createElement('span');
162	    spacer.style.flex = '1';
163	    header.appendChild(spacer);
164	
165	    // Copy button
166	    if (this.showCopyButton) {
167	      const copyBtn = document.createElement('button');
168	      copyBtn.type = 'button';
169	      copyBtn.className = 'cm-codeblock-copy';
170	      copyBtn.textContent = 'Copy';
171	      copyBtn.setAttribute('aria-label', 'Copy code');
172	      const code = this.code;
173	      copyBtn.addEventListener('click', async (e) => {
174	        e.preventDefault();
175	        e.stopPropagation();
176	        try {
177	          await navigator.clipboard.writeText(code);
178	          copyBtn.textContent = 'Copied!';
179	          copyBtn.classList.add('cm-codeblock-copy-success');
180	          setTimeout(() => {
181	            copyBtn.textContent = 'Copy';
182	            copyBtn.classList.remove('cm-codeblock-copy-success');
183	          }, 2000);
184	        } catch {
185	          copyBtn.textContent = 'Failed';
186	          setTimeout(() => { copyBtn.textContent = 'Copy'; }, 2000);
187	        }
188	      });
189	      header.appendChild(copyBtn);
190	    }
191	
192	    // MD button (switch to source mode)
193	    const mdBtn = document.createElement('button');
194	    mdBtn.type = 'button';
195	    mdBtn.className = 'cm-codeblock-toggle';
196	    mdBtn.textContent = 'MD';
197	    mdBtn.setAttribute('aria-label', 'Show markdown source');
198	    const from = this.from;
199	    const to = this.to;
200	    mdBtn.addEventListener('click', (e) => {
201	      e.preventDefault();
202	      e.stopPropagation();
203	      if (!view) return;
204	      view.dispatch({
205	        effects: setCodeBlockSourceMode.of({ from, to, showSource: true }),
206	        scrollIntoView: true,
207	      });
208	      view.focus();
209	    });
210	    header.appendChild(mdBtn);
211	
212	    return header;
213	  }
214	
215	  ignoreEvent(): boolean {
216	    return true;
217	  }
218	}
219	
220	/**
221	 * Footer widget replacing the closing fence line (```)
222	 * Visual element: rounded bottom + background color
223	 */
224	class CodeBlockFooterWidget extends WidgetType {
225	  eq(): boolean {
226	    return true;
227	  }
228	
229	  toDOM(): HTMLElement {
230	    const footer = document.createElement('div');
231	    footer.className = 'cm-codeblock-footer';
232	    return footer;
233	  }
234	
235	  ignoreEvent(): boolean {
236	    return true;
237	  }
238	}
239	
240	// ─── HAST → Mark decorations ──────────────────────────────────────────
241	
242	interface HastNode {
243	  type: string;
244	  value?: string;
245	  tagName?: string;
246	  properties?: { className?: string[] };
247	  children?: HastNode[];
248	}
249	
250	/**
251	 * Convert lowlight HAST tree to Decoration.mark ranges for syntax highlighting.
252	 * Walks the tree and creates mark decorations for text nodes with CSS classes.
253	 */
254	function hastToMarkDecorations(
255	  root: HastNode,
256	  basePos: number
257	): Range<Decoration>[] {
258	  const result: Range<Decoration>[] = [];
259	  let offset = 0;
260	
261	  function walk(node: HastNode, cls?: string) {
262	    if (node.type === 'text') {
263	      const len = node.value?.length || 0;
264	      if (cls && len > 0) {
265	        result.push(
266	          Decoration.mark({ class: cls }).range(
267	            basePos + offset,
268	            basePos + offset + len
269	          )
270	        );
271	      }
272	      offset += len;
273	    } else if (node.type === 'element' || node.type === 'root') {
274	      const nodeClass = node.properties?.className?.join(' ');
275	      const effectiveClass = nodeClass || cls;
276	      if (node.children) {
277	        for (const child of node.children) {
278	          walk(child, effectiveClass);
279	        }
280	      }
281	    }
282	  }
283	
284	  walk(root);
285	  return result;
286	}
287	
288	// ─── Build inline decorations ─────────────────────────────────────────
289	
290	/**
291	 * Build decorations for inline mode:
292	 * - Render mode: replace fences with header/footer widgets, add line + mark decorations
293	 * - Source mode: show full source with toggle button
294	 */
295	function buildCodeBlockInlineDecorations(
296	  state: EditorState,
297	  options: Required<CodeBlockOptions>
298	): DecorationSet {
299	  const decorations: Range<Decoration>[] = [];
300	  const sourceRanges = state.field(codeBlockSourceModeField);
301	
302	  syntaxTree(state).iterate({
303	    enter: (node) => {
304	      if (node.name !== 'FencedCode') return;
305	
306	      // Get language info
307	      const codeInfo = node.node.getChild('CodeInfo');
308	      let language = options.defaultLanguage;
309	      if (codeInfo) {
310	        language = state.doc.sliceString(codeInfo.from, codeInfo.to).trim();
311	      }
312	
313	      // Skip special languages
314	      if (SKIP_LANGUAGES.has(language)) return;
315	
316	      // Get code content
317	      const codeText = node.node.getChild('CodeText');
318	      const code = codeText
319	        ? state.doc.sliceString(codeText.from, codeText.to)
320	        : '';
321	
322	      const showSource = isCodeBlockInSourceMode(
323	        sourceRanges,
324	        node.from,
325	        node.to
326	      );
327	
328	      if (showSource) {
329	        // Source mode: show toggle button + source line styling
330	        const sourceToggleWidget = createCodeBlockSourceToggleWidget(
331	          node.from,
332	          node.to
333	        );
334	        decorations.push(
335	          Decoration.widget({ widget: sourceToggleWidget, block: true }).range(
336	            node.from
337	          )
338	        );
339	
340	        for (let pos = node.from; pos <= node.to; ) {
341	          const line = state.doc.lineAt(pos);
342	          decorations.push(
343	            Decoration.line({ class: 'cm-codeblock-source' }).range(line.from)
344	          );
345	          pos = line.to + 1;
346	        }
347	      } else {
348	        // Render mode (inline): replace fences, keep code content editable
349	
350	        const openFenceLine = state.doc.lineAt(node.from);
351	        const closeFenceLine = state.doc.lineAt(node.to);
352	
353	        // 1. Replace opening fence line with header widget.
354	        //    Use inclusiveEnd so the cursor cannot land between
355	        //    the header and the first content line.
356	        const headerWidget = new CodeBlockHeaderWidget(
357	          language,
358	          code,
359	          node.from,
360	          node.to,
361	          options.copyButton
362	        );
363	        decorations.push(
364	          Decoration.replace({
365	            widget: headerWidget,
366	            block: true,
367	            inclusiveEnd: true,
368	          }).range(openFenceLine.from, openFenceLine.to)
369	        );
370	
371	        // 2. Line decorations for every content line between fences
372	        for (
373	          let lineNum = openFenceLine.number + 1;
374	          lineNum < closeFenceLine.number;
375	          lineNum++
376	        ) {
377	          const line = state.doc.line(lineNum);
378	          decorations.push(
379	            Decoration.line({ class: 'cm-codeblock-content' }).range(line.from)
380	          );
381	        }
382	
383	        // 3. Mark decorations for syntax highlighting (from hast)
384	        if (codeText && code) {
385	          const hast = highlightCodeHast(code, language || undefined);
386	          if (hast) {
387	            const marks = hastToMarkDecorations(hast as HastNode, codeText.from);
388	            for (const mark of marks) {
389	              if (mark.from >= 0 && mark.to <= state.doc.length) {
390	                decorations.push(mark);
391	              }
392	            }
393	          }
394	        }
395	
396	        // 4. Replace closing fence line with footer widget.
397	        //    Use inclusiveStart so the cursor cannot land between
398	        //    the last content line and the footer.
399	        const footerWidget = new CodeBlockFooterWidget();
400	        decorations.push(
401	          Decoration.replace({
402	            widget: footerWidget,
403	            block: true,
404	            inclusiveStart: true,
405	          }).range(closeFenceLine.from, closeFenceLine.to)
406	        );
407	      }
408	    },
409	  });
410	
411	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
412	}
413	
414	// ─── Build standard decorations (auto/toggle) ────────────────────────
415	
416	/**
417	 * Build code block decorations for auto/toggle mode
418	 */
419	function buildCodeBlockDecorations(
420	  state: EditorState,
421	  options: Required<CodeBlockOptions>
422	): DecorationSet {
423	  const decorations: Range<Decoration>[] = [];
424	  const isAutoInteraction = options.interaction === 'auto';
425	  const isDrag = isAutoInteraction ? state.field(mouseSelectingField, false) : false;
426	  const sourceRanges = state.field(codeBlockSourceModeField);
427	
428	  syntaxTree(state).iterate({
429	    enter: (node) => {
430	      if (node.name === 'FencedCode') {
431	        // Get language info
432	        const codeInfo = node.node.getChild('CodeInfo');
433	        let language = options.defaultLanguage;
434	
435	        if (codeInfo) {
436	          language = state.doc.sliceString(codeInfo.from, codeInfo.to).trim();
437	        }
438	
439	        // Skip special languages (like math)
440	        if (SKIP_LANGUAGES.has(language)) {
441	          return;
442	        }
443	
444	        // Get code content
445	        const codeText = node.node.getChild('CodeText');
446	        const code = codeText
447	          ? state.doc.sliceString(codeText.from, codeText.to)
448	          : '';
449	        const codeFrom = codeText ? codeText.from : node.from;
450	
451	        // Calculate start position of each line
452	        const lineStarts: number[] = [];
453	        if (codeText) {
454	          const startPos = codeText.from;
455	          lineStarts.push(startPos);
456	          for (let i = 0; i < code.length; i++) {
457	            if (code[i] === '\n') {
458	              lineStarts.push(startPos + i + 1);
459	            }
460	          }
461	        }
462	
463	        const showSource =
464	          options.interaction === 'toggle'
465	            ? isCodeBlockInSourceMode(sourceRanges, node.from, node.to)
466	            : shouldShowSource(state, node.from, node.to) || isDrag;
467	
468	        if (!showSource) {
469	          // Render mode: show widget
470	          const widget = createCodeBlockWidget({
471	            code,
472	            language,
473	            showLineNumbers: options.lineNumbers,
474	            showCopyButton: options.copyButton,
475	            showSourceToggle: options.interaction === 'toggle',
476	            from: node.from,
477	            to: node.to,
478	            codeFrom,
479	            lineStarts,
480	          });
481	
482	          decorations.push(
483	            Decoration.replace({ widget, block: true }).range(node.from, node.to)
484	          );
485	        } else {
486	          if (options.interaction === 'toggle') {
487	            const sourceToggleWidget = createCodeBlockSourceToggleWidget(
488	              node.from,
489	              node.to
490	            );
491	            decorations.push(
492	              Decoration.widget({ widget: sourceToggleWidget, block: true }).range(
493	                node.from
494	              )
495	            );
496	          }
497	
498	          // Source mode: add background to each line
499	          for (let pos = node.from; pos <= node.to; ) {
500	            const line = state.doc.lineAt(pos);
501	            decorations.push(
502	              Decoration.line({ class: 'cm-codeblock-source' }).range(line.from)
503	            );
504	            pos = line.to + 1;
505	          }
506	        }
507	      }
508	    },
509	  });
510	
511	  return Decoration.set(decorations.sort((a, b) => a.from - b.from), true);
512	}
513	
514	/**
515	 * Create code block StateField
516	 */
517	function createCodeBlockField(
518	  options: Required<CodeBlockOptions>
519	): StateField<DecorationSet> {
520	  const isInline = options.interaction === 'inline';
521	  const buildFn = isInline ? buildCodeBlockInlineDecorations : buildCodeBlockDecorations;
522	
523	  return StateField.define<DecorationSet>({
524	    create(state) {
525	      return buildFn(state, options);
526	    },
527	
528	    update(deco, tr) {
529	      // Rebuild on document or config change
530	      if (
531	        tr.docChanged ||
532	        tr.reconfigured ||
533	        tr.effects.some((effect) => effect.is(setCodeBlockSourceMode))
534	      ) {
535	        return buildFn(tr.state, options);
536	      }
537	
538	      // Inline and toggle modes: don't rebuild on selection change
539	      if (options.interaction !== 'auto') {
540	        return deco;
541	      }
542	
543	      // Rebuild on drag state change
544	      const isDragging = tr.state.field(mouseSelectingField, false);
545	      const wasDragging = tr.startState.field(mouseSelectingField, false);
546	
547	      if (wasDragging && !isDragging) {
548	        return buildFn(tr.state, options);
549	      }
550	
551	      // Keep unchanged during drag
552	      if (isDragging) {
553	        return deco;
554	      }
555	
556	      // Rebuild on selection change
557	      if (tr.selection) {
558	        return buildFn(tr.state, options);
559	      }
560	
561	      return deco;
562	    },
563	
564	    provide: (f) => EditorView.decorations.from(f),
565	  });
566	}
567	
568	/**
569	 * Code block plugin
570	 *
571	 * @param options - Configuration options
572	 * @returns Extension array (StateField + click handler)
573	 *
574	 * @example
575	 * ```typescript
576	 * import { codeBlockField } from 'codemirror-live-markdown';
577	 *
578	 * // Use default config
579	 * extensions: [codeBlockField()]
580	 *
581	 * // Custom config
582	 * extensions: [codeBlockField({
583	 *   lineNumbers: true,
584	 *   copyButton: true,
585	 *   defaultLanguage: 'javascript',
586	 * })]
587	 *
588	 * // Inline mode (editable in-place)
589	 * extensions: [codeBlockField({
590	 *   interaction: 'inline',
591	 *   copyButton: true,
592	 * })]
593	 * ```
594	 */
595	/**
596	 * drawSelection() renders its selection layer behind .cm-content (z-index:-1).
597	 * Inline code-block lines have an opaque background that covers this layer,
598	 * and drawSelection also hides native ::selection via Prec.highest CSS.
599	 *
600	 * Instead of fighting CSS specificity, this ViewPlugin adds Decoration.mark
601	 * spans for selected ranges that overlap code-block content.  These spans
602	 * render INSIDE the .cm-line (above the opaque background), so selection
603	 * is always visible regardless of the browser engine (Chromium, WebKit, etc.).
604	 */
605	const selMark = Decoration.mark({ class: 'cm-codeblock-sel' });
606	
607	const codeBlockSelectionPlugin = ViewPlugin.fromClass(
608	  class {
609	    decorations: DecorationSet;
610	
611	    constructor(view: EditorView) {
612	      this.decorations = this.build(view);
613	    }
614	
615	    update(update: ViewUpdate) {
616	      if (update.docChanged || update.viewportChanged) {
617	        this.decorations = this.build(update.view);
618	        return;
619	      }
620	      if (!update.selectionSet) return;
621	      const isDragging = update.state.field(mouseSelectingField, false);
622	      const wasDragging = update.startState.field(mouseSelectingField, false);
623	      // Rebuild when drag ends so selection marks catch up
624	      if (wasDragging && !isDragging) {
625	        this.decorations = this.build(update.view);
626	        return;
627	      }
628	      // Skip during drag – native/drawSelection handles transient feedback
629	      if (isDragging) return;
630	      this.decorations = this.build(update.view);
631	    }
632	
633	    build(view: EditorView): DecorationSet {
634	      const sel = view.state.selection.main;
635	      if (sel.empty) return Decoration.none;
636	
637	      const ranges: Range<Decoration>[] = [];
638	
639	      syntaxTree(view.state).iterate({
640	        from: sel.from,
641	        to: sel.to,
642	        enter: (node) => {
643	          if (node.name !== 'FencedCode') return;
644	
645	          // Skip special languages (math, mermaid, etc.)
646	          const codeInfo = node.node.getChild('CodeInfo');
647	          if (codeInfo) {
648	            const lang = view.state.doc
649	              .sliceString(codeInfo.from, codeInfo.to)
650	              .trim();
651	            if (SKIP_LANGUAGES.has(lang)) return;
652	          }
653	
654	          // Find content range between fences
655	          const openFenceLine = view.state.doc.lineAt(node.from);
656	          const lastLine = view.state.doc.lineAt(node.to);
657	          const contentFrom = openFenceLine.to + 1;
658	          const contentTo = lastLine.from > contentFrom ? lastLine.from - 1 : contentFrom;
659	
660	          if (contentFrom >= contentTo) return;
661	
662	          // Intersect with selection
663	          const from = Math.max(sel.from, contentFrom);
664	          const to = Math.min(sel.to, contentTo);
665	          if (from < to) {
666	            ranges.push(selMark.range(from, to));
667	          }
668	        },
669	      });
670	
671	      return Decoration.set(ranges, true);
672	    }
673	  },
674	  { decorations: (v) => v.decorations },
675	);
676	
677	const codeBlockSelectionTheme = EditorView.theme({
678	  '.cm-codeblock-sel': {
679	    backgroundColor: 'var(--cm-codeblock-selection, rgba(128, 188, 254, 0.4))',
680	  },
681	});
682	
683	export function codeBlockField(options?: CodeBlockOptions): Extension {
684	  const mergedOptions = { ...defaultOptions, ...options };
685	
686	  const field = createCodeBlockField(mergedOptions);
687	
688	  const extensions: Extension[] = [codeBlockSourceModeField, field];
689	  if (mergedOptions.interaction === 'inline') {
690	    extensions.push(codeBlockSelectionPlugin, codeBlockSelectionTheme);
691	  }
692	  return extensions;
693	}
694	
695	export function codeBlockEditorPlugin(options?: CodeBlockEditorOptions) {
696	  return codeBlockField({
697	    ...options,
698	    interaction: 'toggle',
699	  });
700	}
701	
702	export { setCodeBlockSourceMode };
703

